export type Todo = {
  id: string;
  title: string;
};

// Module-level in-memory store. Persists across requests within the same
// worker isolate. Cleared by `POST /todos.reset`.
export const todos: Todo[] = [];

"use server";

import { serverAction } from "rwsdk/worker";
import { todos } from "./todosState";

// Append a new todo from the submitted form data (`title=<string>`).
// Wrapping with `serverAction(...)` makes this a POST mutation that, after
// running, rehydrates and re-renders the page so the new todo appears.
export const addTodo = serverAction(async (formData: FormData) => {
  const title = String(formData.get("title") ?? "").trim();
  if (!title) return;
  todos.push({ id: crypto.randomUUID(), title });
});

// Remove a todo by id from the submitted form data (`id=<string>`).
export const deleteTodo = serverAction(async (formData: FormData) => {
  const id = String(formData.get("id") ?? "");
  const index = todos.findIndex((t) => t.id === id);
  if (index !== -1) todos.splice(index, 1);
});

import { todos } from "./todosState";
import { addTodo, deleteTodo } from "./actions";

export function TodosPage() {
  return (
    <div>
      <h1>Todos</h1>
      <ul>
        {todos.map((todo) => (
          <li key={todo.id}>
            <span data-testid="todo-item">{todo.title}</span>{" "}
            <form action={deleteTodo} style={{ display: "inline" }}>
              <input type="hidden" name="id" value={todo.id} />
              <button type="submit">Delete</button>
            </form>
          </li>
        ))}
      </ul>
      <form action={addTodo}>
        <input name="title" />
        <button type="submit">Add Todo</button>
      </form>
    </div>
  );
}

import { render, route } from "rwsdk/router";
import { defineApp } from "rwsdk/worker";

import { Document } from "@/app/document";
import { setCommonHeaders } from "@/app/headers";
import { Home } from "@/app/pages/home";
import { TodosPage } from "@/app/pages/todos/TodosPage";
import { todos } from "@/app/pages/todos/todosState";

export type AppContext = {};

export default defineApp([
  setCommonHeaders(),
  ({ ctx }) => {
    // setup ctx here
    ctx;
  },
  render(Document, [
    route("/", Home),
    route("/todos", TodosPage),
    route("/todos.json", {
      get: () =>
        Response.json({
          todos: todos.map(({ id, title }) => ({ id, title })),
        }),
    }),
    route("/todos.reset", {
      post: () => {
        todos.length = 0;
        return new Response("reset");
      },
    }),
  ]),
]);
